import pandas as pd

D = "data"
files = {
    "le": f"{D}/life_expectancy/API_SP.DYN.LE00.IN_DS2_en_csv_v2_259172.csv",
    "hx": f"{D}/health_expenditure_per_capita/API_SH.XPD.CHEX.PC.CD_DS2_en_csv_v2_3808.csv",
    "gdp": f"{D}/gdp_per_capita_ppp/API_NY.GDP.PCAP.PP.CD_DS2_en_csv_v2_1247.csv",
}
meta = pd.read_csv(f"{D}/life_expectancy/Metadata_Country_API_SP.DYN.LE00.IN_DS2_en_csv_v2_259172.csv")
print(meta.columns.tolist(), len(meta))
print(meta["Region"].notna().sum(), "with region")
years = [str(y) for y in range(1960, 2026)]
wide = {}
for k, f in files.items():
    df = pd.read_csv(f, skiprows=4)
    wide[k] = df.set_index("Country Code")[years].apply(pd.to_numeric, errors="coerce")
ctry = set(meta.loc[meta["Region"].notna(), "Country Code"])
for y in range(2000, 2026):
    c = str(y)
    ok = {k: set(wide[k].index[wide[k][c].notna()]) & ctry for k in wide}
    print(y, {k: len(v) for k, v in ok.items()}, "all3:", len(ok["le"] & ok["hx"] & ok["gdp"]))

